mapper.select:
select e.*, u.user_name, u.status account_status, u.dept_id, d.dept_name,
       s.site_name, s.status site_status
from att_employee e join sys_user u on u.user_id = e.user_id
left join sys_dept d on d.dept_id = u.dept_id
join att_site s on s.site_id = e.site_id

    and e.employee_id = #{employeeId}
    and e.employee_no like concat('%', #{employeeNo}, '%')
    and e.employee_name like concat('%', #{employeeName}, '%')
    and u.dept_id = #{deptId}
    and e.site_id = #{siteId}
    and e.status = #{status}
    ${params.dataScope}

order by e.employee_id desc

select u.user_id id, concat(u.user_name, ' / ', u.nick_name) label, u.status, u.dept_id, d.dept_name from sys_user u join sys_dept d on d.dept_id = u.dept_id where u.del_flag = '0' and u.status = '0' and d.del_flag = '0' and d.status = '0' and not exists (select 1 from att_employee e where e.user_id = u.user_id) and u.user_id = #{userId}
and (u.user_name like concat('%', #{userName}, '%') or u.nick_name like concat('%', #{userName}, '%'))
${params.dataScope} order by u.user_id limit 100
